# This test drives `Req.Test` through Plug; it is active only when
# `plug` is loaded. To run it, add `{:plug, "~> 1.0"}` to your deps
# — for all environments, not `only: :test`: `req` declares `plug`
# as an optional all-environment dependency, and a narrower scope
# diverges from it.
if Code.ensure_loaded?(Plug.Conn) do
  defmodule OhipDemo.Integrations.OhipOauthTest do
    @moduledoc false

    # Generated by Hearth — verifies the auth scheme wired into
    # OhipDemo.Integrations.OhipOauth attaches credentials at request time.
    # The tests double as examples of every way to supply the credential.
    # Hearth-owned: regenerated on every `mix hearth.gen` run.

    use ExUnit.Case, async: false

    @client OhipDemo.Integrations.OhipOauth
    @api_key "hearth-test-credential"

    # Values Layer 1 takes per call, never from config.
    @opts [
      api_key: @api_key,
      headers: [
        {"x-app-key", "hearth-test-x-app-key"},
        {"enterpriseid", "hearth-test-enterpriseid"}
      ],
      base_url: "http://hearth.test"
    ]

    # Without `api_key:`, OhipDemo.Tenancy.client_credentials/1 resolves the credential —
    # it's yours to test.
    test "request! sends basic auth from the api_key: option" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "authorization") == [
                 "Basic " <> Base.encode64(@api_key)
               ]

        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} = @client.request!("/ping", @opts ++ [plug: plug])
    end

    test "a per-call api_key: may be a function" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "authorization") == [
                 "Basic cGVyLWNhbGwtZnVuY3Rpb24="
               ]

        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, api_key: fn -> "per-call-function" end]
               )
    end

    test "a credential set explicitly on the request wins" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "authorization") == [
                 "Basic ZXhwbGljaXQtY3JlZGVudGlhbA=="
               ]

        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, auth: {:basic, "explicit-credential"}]
               )
    end

    # Without the header on the request, OhipDemo.Tenancy.app_key/1 resolves
    # x-app-key — it's yours to test.
    test "an explicit x-app-key header wins" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "x-app-key") == ["explicit-credential"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, headers: [{"x-app-key", "explicit-credential"}]]
               )
    end

    # Without the header on the request, OhipDemo.Tenancy.enterprise_id/1 resolves
    # enterpriseid — it's yours to test.
    test "an explicit enterpriseid header wins" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "enterpriseid") == ["explicit-credential"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, headers: [{"enterpriseid", "explicit-credential"}]]
               )
    end
  end
end
